import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.CA63_VWy.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PHP/Laravel Handbook","text":"Guia completo para quem desenvolve PHP/Laravel","tagline":"Do básico à arquitetura. Tradução pt-BR por IA — Vinícius Freire","actions":[{"theme":"brand","text":"Começar","link":"/01-php-basics/01-types"},{"theme":"alt","text":"Roadmap","link":"/roadmap"},{"theme":"alt","text":"Mentoria","link":"https://codemate.team"}]},"features":[{"icon":"📚","title":"141 temas","details":"Da sintaxe básica de PHP à arquitetura de microsserviços. Material organizado, com código e exercícios práticos."},{"icon":"🎯","title":"Preparação para entrevista","details":"Cada tema tem a seção \\"Na entrevista\\", com resposta pronta e perguntas reais de empresa."},{"icon":"💼","title":"Experiência real","details":"Baseado em entrevistas de verdade e em projetos de empresas grandes."},{"icon":"🗺️","title":"Roadmap","details":"Plano claro do Junior ao Senior. Você sabe o que estudar em cada etapa."},{"icon":"👨‍🏫","title":"Mentoria","details":"O material entra no programa de mentoria da CodeMate, para quem está saindo para o mercado."},{"icon":"⚡","title":"Stack atual","details":"PHP 8.2+, Laravel 11, PostgreSQL, Docker, Redis, RabbitMQ, Kafka — o que as vagas pedem hoje."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1787679091000}'),i={name:"index.md"};function s(n,e,l,d,p,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h2 id="estrutura" tabindex="-1">Estrutura <a class="header-anchor" href="#estrutura" aria-label="Permalink to &quot;Estrutura&quot;">​</a></h2><p>O handbook tem 22 seções, do simples ao avançado:</p><h3 id="junior" tabindex="-1">Junior <a class="header-anchor" href="#junior" aria-label="Permalink to &quot;Junior&quot;">​</a></h3><p><strong>Fundamentos de PHP</strong></p><ul><li>Tipos, variáveis, operadores</li><li>Funções, arrays, strings</li><li>OOP: classes, interfaces, traits</li></ul><p><strong>Git &amp; Workflow</strong></p><ul><li>Git básico, branches, conflitos</li><li>Git Flow, trabalho em time</li></ul><p><strong>Laravel Basics</strong></p><ul><li>Arquitetura do framework</li><li>Routing, Controllers, Middleware</li><li>Service Container, Service Providers</li></ul><h3 id="middle" tabindex="-1">Middle <a class="header-anchor" href="#middle" aria-label="Permalink to &quot;Middle&quot;">​</a></h3><p><strong>Laravel Advanced</strong></p><ul><li>Eloquent, Query Builder</li><li>Events, Jobs, Queues</li><li>API Resources, Validation</li></ul><p><strong>Bancos de dados</strong></p><ul><li>SQL, transações, índices</li><li>Otimização de query, problema N+1</li><li>Recursos avançados do PostgreSQL</li></ul><p><strong>Testing &amp; Security</strong></p><ul><li>Testes Unit e Feature, TDD</li><li>XSS, CSRF, SQL Injection</li><li>Authentication, Authorization</li></ul><h3 id="senior" tabindex="-1">Senior <a class="header-anchor" href="#senior" aria-label="Permalink to &quot;Senior&quot;">​</a></h3><p><strong>Arquitetura</strong></p><ul><li>SOLID, Design Patterns</li><li>DDD, CQRS, Event Sourcing</li><li>Repository, Service Layer</li></ul><p><strong>Infra</strong></p><ul><li>Docker, CI/CD</li><li>Cache (Redis, Memcached)</li><li>Message Brokers (RabbitMQ, Kafka)</li></ul><p><strong>Highload</strong></p><ul><li>Otimização de performance</li><li>Escalabilidade</li><li>Arquitetura de microsserviços</li></ul><hr><h2 id="como-usar" tabindex="-1">Como usar <a class="header-anchor" href="#como-usar" aria-label="Permalink to &quot;Como usar&quot;">​</a></h2><p><strong>Para estudar</strong> Leia na ordem, do simples ao avançado. Cada tema leva 10–15 minutos e tem código.</p><p><strong>Antes da entrevista</strong> Use <strong>Na entrevista</strong> em cada tema para revisar rápido.</p><p><strong>Para praticar</strong> Faça os exercícios no fim de cada tema. Leve os patterns para os seus projetos.</p><p><strong>Com mentor</strong> O handbook entra no programa de mentoria, para uma preparação organizada rumo à vaga.</p><hr><h2 id="sobre-o-projeto" tabindex="-1">Sobre o projeto <a class="header-anchor" href="#sobre-o-projeto" aria-label="Permalink to &quot;Sobre o projeto&quot;">​</a></h2><p>Feito pela equipe CodeMate com base em entrevistas reais e projetos comerciais. O material é atualizado conforme o mercado muda.</p><p><strong>Tradução pt-BR</strong> Esta edição em português brasileiro foi traduzida por IA por <a href="https://github.com/alencarfreire" target="_blank" rel="noreferrer">Vinícius Freire</a>.</p><p><strong>Open Source</strong> O código está no <a href="https://github.com/alencarfreire/php-handbook" target="_blank" rel="noreferrer">GitHub</a>. Contributions são bem-vindas.</p><p><strong>Mentoria</strong> Se você quer ajuda com vaga, code review ou entrevista — veja o programa em <a href="https://codemate.team" target="_blank" rel="noreferrer">codemate.team</a>.</p>',35)])])}const g=a(i,[["render",s]]);export{m as __pageData,g as default};
